const STORAGEKEY="toc-storage-key";export const defaultOptions={headerTitle:"Table of Contents",fontFamily:"serif",color:"#0099ff",disableDottedLines:!1,disableTocLinks:!1,tocLevelIndentation:1,tocTextSizeShrink:1,depth:4};export const saveOptionsFn=t=>{localStorage.setItem(STORAGEKEY,JSON.stringify(t))};export const getOptionsFn=()=>{const t=localStorage.getItem(STORAGEKEY)||"";try{return JSON.parse(t)}catch(t){return null}};